using System;using System.Collections.Generic;using System.IO;using Ashfall.Core;using Ashfall.Integration.Playable.HandsWeapons;using Ashfall.Modules.HealthStates;
namespace Ashfall.Integration.Playable.Networking {
 public sealed partial class R24LanLobby {
  const string EquipmentCommand="playable.equipment/1";
  sealed class EquippedWeapon {internal string Id;internal int Hand;internal bool Suppressed,Blocked;internal double At,SampleAt;internal long Life=-1;internal R24MeleeRuntime Blade;internal R23ShotPose Model;}
  readonly Dictionary<string,EquippedWeapon> equipment=new Dictionary<string,EquippedWeapon>(StringComparer.Ordinal);
  // A declaration selects existing custody only. No lease, pose, damage or item is minted.
  public bool RequestEquipment(string id,int hand,bool suppressed,bool blocked=false){Check();if(hand<0||hand>1||id!=null&&!Ashfall.Modules.Networking.Wire.IsText(id,128,false))return false;if(State==R24LanLobbyState.Hosting)return ApplyEquipment(OwnActor,id,hand,suppressed,blocked);if(State!=R24LanLobbyState.Connected)return false;using(var m=new MemoryStream())using(var w=new BinaryWriter(m,Utf8)){w.Write(id!=null);if(id!=null)Write(w,id,128);w.Write((byte)hand);w.Write(suppressed);w.Write(blocked);return QueueGameCommand(EquipmentCommand,m.ToArray());}}
  bool ApplyEquipment(string actor,string id,int hand,bool suppressed,bool blocked){CombatActor owner;if(!InventoryLive||hand<0||hand>1||!combat.TryGetValue(actor,out owner)||id!=null&&(!owner.Weapons.ContainsKey(id)||owner.Weapons[id].Profile=="smaw"&&owner.Weapons[id].Ammo==0&&owner.Weapons[id].RocketReloads==0))return false;EquippedWeapon prior;if(!equipment.TryGetValue(actor,out prior)||prior.Id!=id||prior.Hand!=hand||prior.Suppressed!=suppressed||prior.Blocked!=blocked){if(prior!=null&&prior.Blade!=null)prior.Blade.Retire();prior=new EquippedWeapon{Id=id,Hand=hand,Suppressed=suppressed,Blocked=blocked};equipment[actor]=prior;CombatWeapon weapon;if(id!=null&&owner.Weapons.TryGetValue(id,out weapon)){var profile=R24MeleeProfiles.ForId(weapon.Profile);if(profile!=null)prior.Blade=new R24MeleeRuntime(id,profile);}}prior.At=clock.Now;return true;}
  void ReadEquipment(string actor,byte[] bytes){try{using(var m=new MemoryStream(bytes,false))using(var r=new BinaryReader(m,Utf8)){string id=r.ReadBoolean()?Read(r,128):null;int hand=r.ReadByte();bool suppressed=r.ReadBoolean(),blocked=r.ReadBoolean();if(m.Position==m.Length)ApplyEquipment(actor,id,hand,suppressed,blocked);}}catch(InvalidDataException){}catch(IOException){}catch(ArgumentException){}}
  bool ControlsBlocked(string actor){EquippedWeapon e;return equipment.TryGetValue(actor,out e)&&clock.Now-e.At<=.5&&e.Blocked;}
  bool HandOccupied(string actor,int hand){EquippedWeapon e;CombatActor c;return equipment.TryGetValue(actor,out e)&&!e.Suppressed&&e.Id!=null&&clock.Now-e.At<=.5&&combat.TryGetValue(actor,out c)&&c.Weapons.ContainsKey(e.Id)&&(c.Weapons[e.Id].Profile!="smaw"||c.Weapons[e.Id].Ammo>0||c.Weapons[e.Id].RocketReloads>0)&&(e.Hand==hand||c.Weapons[e.Id].Hands!=null);}
  void ClearEquipment(){ClearMeleeExpansion();foreach(var e in equipment.Values)if(e.Blade!=null)e.Blade.Retire();equipment.Clear();}
  static R23ShotPose Basis(R24LanTransform t){return new R23ShotPose(t.Position,Rotate(t.Rotation,new Float3(1,0,0)),Rotate(t.Rotation,new Float3(0,1,0)),Rotate(t.Rotation,new Float3(0,0,1)));}
  static R23ShotPose GripBasis(R24LanTransform t){return new R23ShotPose(t.Position,Rotate(t.Rotation,new Float3(1,0,0)),Rotate(t.Rotation,new Float3(0,0,1)),Rotate(t.Rotation,new Float3(0,-1,0)));}
  bool MapBladeClear(Float3 a,Float3 b){float distance=(float)Math.Sqrt(Distance2(a,b));if(distance<.00001f)return true;float hit=ballisticTrace==null?0:ballisticTrace(a,Normalize(Sub(b,a)),distance);return !Single.IsNaN(hit)&&hit>=distance-.005f;}
  bool MeleeVisible(Float3 from,Float3 to,string panel){float length=(float)Math.Sqrt(Distance2(from,to));if(length<.00001f)return true;if(ballisticTrace==null)return false;var d=Normalize(Sub(to,from));float block=ballisticTrace(from,d,length);if(Single.IsNaN(block)||block<length-.005f)return false;float distance;string first=NearestSharedPanel(from,d,length,out distance);return first==null||first==panel;}
  string[] MeleeOverlaps(string actor,R23ShotPose model,Float3 a,Float3 b,Float3 c,Float3 d,float margin){var found=new List<KeyValuePair<string,double>>();Float3[] v;int[] triangles;if(!R24KnifeHull.TryBuild(R24KnifeMath.HullPoints(a,b,c,d,margin+.001f),out v,out triangles))return new string[0];
   foreach(var member in sessions.CaptureMembers()){if(member.ActorId==actor)continue;var health=hostHealth.Read(member.CanonicalActorId);R24LanRawTrackingSample raw;if(health==null||!health.Connected||health.Life!=LifeState.Alive||!Fresh(member.ActorId,clock.Now,out raw))continue;var head=raw.Pose.Head.Position;bool hit=false;foreach(var sphere in new[]{new Float3(head.X,head.Y,head.Z),new Float3(head.X,head.Y-.45f,head.Z),new Float3(head.X,head.Y-.92f,head.Z)}){float radius=sphere.Y==head.Y?.17f:sphere.Y==head.Y-.45f?.29f:.27f;if(R24LanMeleeGeometry.Sphere(v,triangles,sphere,radius)&&MeleeVisible(model.Origin,sphere,null)){hit=true;break;}}if(hit)found.Add(new KeyValuePair<string,double>("actor/"+member.ActorId,Distance2(model.Origin,head)));}
   foreach(var panel in sharedPanels.Values)if(R24LanMeleeGeometry.Box(v,triangles,panel.Shape)&&MeleeVisible(model.Origin,panel.Shape.Center,panel.Id))found.Add(new KeyValuePair<string,double>("panel/"+panel.Id,Distance2(model.Origin,panel.Shape.Center)));
   found.Sort(delegate(KeyValuePair<string,double> x,KeyValuePair<string,double> y){int order=x.Value.CompareTo(y.Value);return order!=0?order:String.CompareOrdinal(x.Key,y.Key);});var ids=new string[found.Count];for(int i=0;i<ids.Length;i++)ids[i]=found[i].Key;return ids;
  }
  void SampleMeleePose(string actor,R24LanRawTrackingSample sample){SampleFists(actor,sample);EquippedWeapon e;if(!equipment.TryGetValue(actor,out e)||e.Blade==null)return;var member=sessions.Get(actor);var health=member==null?null:hostHealth.Read(member.CanonicalActorId);CombatActor owner;bool usable=InventoryLive&&!e.Suppressed&&!e.Blocked&&clock.Now-e.At<=.5&&health!=null&&health.Connected&&health.Life==LifeState.Alive&&combat.TryGetValue(actor,out owner)&&owner.Weapons.ContainsKey(e.Id)&&!sample.Pose.Paddles&&(sample.Pose.Flags&(e.Hand==0?2:4))!=0;
   float dt=(float)(sample.Time-e.SampleAt);e.SampleAt=sample.Time;if(!usable||dt<=0||dt>.15f||e.Life!=health.LifeGeneration){e.Blade.SuspendControls();e.Life=health==null?-1:health.LifeGeneration;if(!usable)return;dt=.04f;}
   var hand=e.Hand==0?sample.Pose.Left:sample.Pose.Right;var grip=GripBasis(hand);e.Model=grip;var a=e.Model.Point(e.Blade.Profile.Base);var b=e.Model.Point(e.Blade.Profile.Tip);
   if(rawWorldClear==null||!rawWorldClear(sample.Pose.Head.Position,hand.Position)||!MapBladeClear(hand.Position,a)||!MapBladeClear(hand.Position,b)){e.Blade.SuspendControls();return;}
   var other=e.Hand==0?sample.Pose.Right:sample.Pose.Left;bool tracked=(sample.Pose.Flags&(e.Hand==0?4:2))!=0;FoodPreparation food;bool reserved=foodPreparations.TryGetValue(actor,out food)&&food.Hand!=e.Hand||GrenadeHandOccupied(actor,1-e.Hand);e.Blade.UpdateSupport(true,tracked,reserved,(e.Hand==0?sample.Pose.RightGrip:sample.Pose.LeftGrip)>.7f,(float)Math.Sqrt(Distance2(other.Position,e.Model.Point(R24MeleeRuntime.SupportPoint))));
   SampleBladeClash(actor,e,a,b,sample);var overlaps=MeleeOverlaps(actor,e.Model,a,b,a,b,0);var sweep=e.Blade.BeginFrame(dt,true,Basis(sample.Pose.Root),a,b,hand.Position,overlaps);if(sweep==null)return;
   for(int step=0;step<sweep.Steps;step++){Float3 oldA,oldB,nextA,nextB;sweep.ReadStep(step,out oldA,out oldB,out nextA,out nextB);var swept=MeleeOverlaps(actor,e.Model,oldA,oldB,nextA,nextB,0);var current=MeleeOverlaps(actor,e.Model,nextA,nextB,nextA,nextB,0);var retained=MeleeOverlaps(actor,e.Model,nextA,nextB,nextA,nextB,R24MeleeRuntime.ExitHysteresis);foreach(var entry in e.Blade.SampleStep(sweep,step,swept,current,retained))e.Blade.ApplyContact(entry,delegate(string target,float damage){if(MeleeBlocked(actor))return false;if(target.StartsWith("panel/",StringComparison.Ordinal)){DamageSharedPanel(target.Substring(6),damage*GameplayRules.BuildDamage);return true;}return QueueMeleeDamage(actor,target.Substring(6),damage,e.Model.Origin,e.Hand,"blade");});}
  }
  float GuardDistance(string shooter,Float3 from,Float3 direction,float range){foreach(var pair in equipment){if(pair.Key==shooter)continue;var e=pair.Value;var member=sessions.Get(pair.Key);var h=member==null?null:hostHealth.Read(member.CanonicalActorId);CombatActor custody;R24LanRawTrackingSample raw;if(e.Id==null||e.Blade==null||h==null||h.Life!=LifeState.Alive||!combat.TryGetValue(pair.Key,out custody)||!custody.Weapons.ContainsKey(e.Id)||e.Blade==null||e.Suppressed||e.Blocked||clock.Now-e.At>.5||!Fresh(pair.Key,clock.Now,out raw)||clock.Now-e.SampleAt>.15)continue;Ashfall.Modules.Combat.BulletGuard guard;if(e.Blade.TryReadBulletGuard(e.Model,true,out guard)){float fraction;if(guard.Intersects(from,R24KnifeMath.Add(from,R24KnifeMath.Scale(direction,range)),out fraction))range=Math.Min(range,range*fraction);}}return range;}
 }
}
